const saves = ['{"score": 12}', "{broken save", '{"score": 30}'];

for (const text of saves) {
  try {
    const data = JSON.parse(text);
    console.log("Score:", data.score);
  } catch (error) {
    console.log("Couldn't read it:", error.name);
  } finally {
    console.log("---");
  }
}

const tests = [
  () => undefinedVariable + 1,
  () => null.length,
  () => JSON.parse("{"),
  () => { throw new Error("My own error"); },
];

for (const test of tests) {
  try {
    test();
  } catch (error) {
    console.error(error.name + ": " + error.message);
  }
}

console.table([{ name: "Ada", score: 12 }, { name: "Ben", score: 30 }]);

