tasks.solution:
function safeParse(text) {
  // put JSON.parse inside try/catch; return null if it fails
  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
}

console.log(safeParse('{"score": 42}'));
console.log(safeParse("{broken"));

