tasks.solution:
function launch(ok) {
  const steps = [];
  // try / catch / finally
  try {
    if (!ok) throw new Error("Engine failure");
    steps.push("Launch successful");
  } catch (error) {
    steps.push("Problem: " + error.message);
  } finally {
    steps.push("Panel closed");
  }
  return steps;
}

console.log(launch(true));
console.log(launch(false));

