project_task.solution:
const DEFAULT_SAVE = { best: 0, level: 1 };

function loadSave() {
  const text = localStorage.getItem("starSave");
  // make JSON.parse safe with try/catch
  if (text === null) return { ...DEFAULT_SAVE };
  try {
    return JSON.parse(text);
  } catch (error) {
    console.warn("Save is broken, starting from scratch.");
    return { ...DEFAULT_SAVE };
  }
}

const save = loadSave();
document.querySelector("#info").textContent = `Best: ${save.best} · Level: ${save.level}`;
